-- GWM: lengkapi poster + info semua event mendatang dan TERBITKAN. Jalankan di Supabase > SQL Editor.
-- Jalankan SETELAH events_mendatang.sql. Aman dijalankan ulang.
-- poster_url: URL gambar resmi (Visit Indonesia / Jadwal Event) bila ada; selain itu banner buatan GWM di assets/posters/ (pengganti sementara).
-- Ganti dengan poster resmi lewat admin bila sudah ada izin penyelenggara.
update events e set
  poster_url=v.poster, ticket_url=v.ticket, price_label=v.price, lineup=coalesce(v.lineup,e.lineup),
  source_ig=coalesce(v.ig,e.source_ig), description=v.descr, status='published'
from (values
 ('guns-n-roses-jakarta-2026','https://www.indonesia.travel/contentassets/319cc21006244296b7c97c23ed1c4cb3/gnr.jpeg','https://gnrjakarta.com/','Rp1.750.000 – Rp7.500.000','Axl Rose, Slash, Duff McKagan','rajawaliindonesia','Guns N'' Roses World Tour 2026 di Madya Stadium GBK, Sabtu 21 November 2026. Dipromotori Rajawali Indonesia dan dipersembahkan balé by BTN. Kategori: VIP, Festival A–C, Tribune A–B. Harga general sale belum termasuk PPN 10%, platform fee 5%, dan convenience fee.'),
 ('do-day-off-jakarta-2026','assets/posters/do-day-off-jakarta-2026.jpg','https://dohkyungsoojakarta2026.com/','Rp1.350.000 – Rp3.500.000','D.O. (Doh Kyung-soo)',null,'Konser solo D.O. (EXO) bertajuk DAY OFF, dua hari di Istora Senayan, 21–22 November 2026. Kategori tiket: CAT 1–4 dan Special Day Package. Harga belum termasuk pajak dan biaya layanan.'),
 ('my-chemical-romance-jakarta-2026','https://www.indonesia.travel/contentassets/9f52aece2e8145fd8a7ffe2d4ae15ca7/mcr.jpg','https://mcrjakarta.com/','Mulai Rp1.059.000','My Chemical Romance','mychemicalromance','Konser solo My Chemical Romance di Jakarta International Stadium (JIS), 22 November 2026. Band emo/alternative rock asal Amerika Serikat ini dikenal lewat Welcome to the Black Parade, Helena, dan I''m Not Okay (I Promise).'),
 ('josjis-fest-vol-2-2026','https://cdn.jadwal.events/events/2026/09/01M28NC8GRS3XXC3AQ6FWXQ0SQ.webp','https://jadwal.events/e/josjis-fest-vol2','Mulai Rp89.000',null,null,'Josjis Fest Vol.2, festival musik di Alun-Alun Ponorogo, Jawa Timur, 22 November 2026. Tiket mulai Rp89.000 lewat Jadwal Event.'),
 ('simple-plan-jakarta-2026','https://www.indonesia.travel/contentassets/cd44ef3a0e424fd59e9f1e37e7b7f490/simple-plan.jpg','https://www.indonesia.travel/gb/en/events/event-detail/simple-plan','Mulai Rp950.000','Simple Plan, LØLØ (special guest)',null,'Simple Plan membawa THE BIGGER THAN YOU THINK! TOUR, perayaan 25 tahun karier, ke Tennis Indoor Senayan, Jumat 27 November 2026. Setlist spesial berisi hits seperti Welcome to My Life, Perfect, dan I''m Just a Kid.'),
 ('simple-plan-surabaya-2026','https://www.indonesia.travel/contentassets/cd44ef3a0e424fd59e9f1e37e7b7f490/simple-plan.jpg','https://www.indonesia.travel/gb/en/events/event-detail/simple-plan','Mulai Rp950.000','Simple Plan, LØLØ (special guest)',null,'Simple Plan membawa THE BIGGER THAN YOU THINK! TOUR ke Jatim Expo Surabaya, Sabtu 28 November 2026, dengan LØLØ sebagai special guest. Ini pemberhentian terakhir tur di Indonesia.'),
 ('kings-of-convenience-jakarta-2026','https://www.indonesia.travel/contentassets/518f3047f6484be895a72316ea393fc5/koc.png','http://kocjakarta.com/','Rp975.000 – Rp1.500.000','Kings of Convenience',null,'Duo indie folk Norwegia Erlend Øye dan Eirik Glambek Bøe tampil dua malam di JIEXPO Convention Centre & Theatre, 28–29 November 2026, mulai 20.00 WIB. Semua kursi bernomor (all-seated). Harga belum termasuk pajak dan biaya platform.'),
 ('boynextdoor-tangerang-2026','assets/posters/boynextdoor-tangerang-2026.jpg',null,'Info menyusul','BOYNEXTDOOR',null,'Konser boy group K-pop BOYNEXTDOOR (tur Knock On Vol.2) di ICE BSD City, Tangerang, 5 Desember 2026. Pantau kanal resmi penyelenggara untuk info tiket.'),
 ('5sos-jakarta-2026','assets/posters/5sos-jakarta-2026.jpg','https://5sosjakarta.com/','Cek kategori di situs resmi','5 Seconds of Summer',null,'Pertunjukan tambahan 5 Seconds of Summer (Everyone''s a Star! World Tour) di Indonesia Arena GBK, 6 Desember 2026, setelah tiket show pertama habis dalam waktu singkat.'),
 ('dwp-2026','https://www.indonesia.travel/contentassets/497f63f035794e43ab1a1ba4d070ebfb/dwp-2026.webp','https://dwpfest.com/','Mulai Rp1.700.000 (3-day pass)','Alok, Afrojack, R3HAB, Axwell, Sebastian Ingrosso, Dimitri Vegas, Dimension','dwpfest','Djakarta Warehouse Project (DWP) 2026, festival musik elektronik tiga hari oleh Ismaya Live, 11–13 Desember 2026 di Jakarta (JIExpo Kemayoran menurut pemberitaan). Line-up dan venue dapat berubah; cek kanal resmi.'),
 ('dimash-dimensions-bogor-2026','assets/posters/dimash-dimensions-bogor-2026.jpg','https://dqdimensionsworldtourina.com/','Rp850.000 – Rp8.700.000','Dimash Qudaibergen',null,'Konser solo perdana Dimash Qudaibergen di Indonesia (DIMENSIONS World Tour), 12 Desember 2026 di Sentul International Convention Center. Format all-seated, enam kategori tiket, harga belum termasuk pajak dan biaya platform.'),
 ('gaikindo-auto-week-2026-tangerang','assets/posters/gaikindo-auto-week-2026-tangerang.jpg',null,'Info menyusul',null,null,'Gaikindo Auto Week (GAW) 2026 di ICE BSD City, Tangerang, 20–29 November 2026. Pameran otomotif akhir tahun dengan penawaran khusus, test drive, dan aktivitas keluarga. Area pameran 90.000 m2 dengan lebih dari 65 merek kendaraan serta 30 merek industri pendukung.'),
 ('gaikindo-auto-week-2026-denpasar','assets/posters/gaikindo-auto-week-2026-denpasar.jpg',null,'Info menyusul',null,null,'Gaikindo Auto Week (GAW) 2026 di Living World Denpasar, 25–29 November 2026. Pameran otomotif akhir tahun dengan penawaran khusus, test drive, dan aktivitas keluarga. Seri regional dengan 12 merek peserta.'),
 ('gaikindo-auto-week-2026-balikpapan','assets/posters/gaikindo-auto-week-2026-balikpapan.jpg',null,'Info menyusul',null,null,'Gaikindo Auto Week (GAW) 2026 di e-Walk Mall Balikpapan Superblock, 25–29 November 2026. Pameran otomotif akhir tahun dengan penawaran khusus, test drive, dan aktivitas keluarga. Seri regional dengan 9 merek peserta.'),
 ('gaikindo-auto-week-2026-bandung','assets/posters/gaikindo-auto-week-2026-bandung.jpg',null,'Info menyusul',null,null,'Gaikindo Auto Week (GAW) 2026 di Summarecon Mall Bandung, 25–29 November 2026. Pameran otomotif akhir tahun dengan penawaran khusus, test drive, dan aktivitas keluarga. Seri regional dengan 10 merek peserta.'),
 ('gaikindo-auto-week-2026-makassar','assets/posters/gaikindo-auto-week-2026-makassar.jpg',null,'Info menyusul',null,null,'Gaikindo Auto Week (GAW) 2026 di Trans Studio Mall Makassar, 25–29 November 2026. Pameran otomotif akhir tahun dengan penawaran khusus, test drive, dan aktivitas keluarga. Seri regional dengan 10 merek peserta.'),
 ('gaikindo-auto-week-2026-medan','assets/posters/gaikindo-auto-week-2026-medan.jpg',null,'Info menyusul',null,null,'Gaikindo Auto Week (GAW) 2026 di Sun Plaza Medan, 25–29 November 2026. Pameran otomotif akhir tahun dengan penawaran khusus, test drive, dan aktivitas keluarga. Seri regional di Medan.'),
 ('gaikindo-auto-week-2026-palembang','assets/posters/gaikindo-auto-week-2026-palembang.jpg',null,'Info menyusul',null,null,'Gaikindo Auto Week (GAW) 2026 di Palembang Icon Mall, 25–29 November 2026. Pameran otomotif akhir tahun dengan penawaran khusus, test drive, dan aktivitas keluarga. Seri regional dengan 12 merek peserta.'),
 ('gaikindo-auto-week-2026-semarang','assets/posters/gaikindo-auto-week-2026-semarang.jpg',null,'Info menyusul',null,null,'Gaikindo Auto Week (GAW) 2026 di 23 Mall Semarang, 25–29 November 2026. Pameran otomotif akhir tahun dengan penawaran khusus, test drive, dan aktivitas keluarga. Seri regional di Semarang (nama mal sesuai pemberitaan).'),
 ('gaikindo-auto-week-2026-solo','assets/posters/gaikindo-auto-week-2026-solo.jpg',null,'Info menyusul',null,null,'Gaikindo Auto Week (GAW) 2026 di The Park Mall Solo Baru, 25–29 November 2026. Pameran otomotif akhir tahun dengan penawaran khusus, test drive, dan aktivitas keluarga. Seri regional dengan 11 merek peserta.'),
 ('gaikindo-auto-week-2026-surabaya','assets/posters/gaikindo-auto-week-2026-surabaya.jpg',null,'Info menyusul',null,null,'Gaikindo Auto Week (GAW) 2026 di Pakuwon Mall Surabaya, 25–29 November 2026. Pameran otomotif akhir tahun dengan penawaran khusus, test drive, dan aktivitas keluarga. Seri regional dengan 10 merek peserta.')
) as v(slug,poster,ticket,price,lineup,ig,descr)
where e.slug=v.slug;

-- Cek: semua harus status published
-- select title, status, poster_url is not null as poster, ticket_url is not null as tiket from events where created_at>now()-interval '7 days' order by event_date;
